import {rotate} from './fields.js';
import {localAnchor} from './connections.js';
export function distanceToCollider(point,object,part,pose){const inverse=[-pose.q[0],-pose.q[1],-pose.q[2],pose.q[3]],local=rotate(point.map((v,i)=>v-pose.p[i]),inverse).map((v,i)=>v/(object.size[i]*(object.mirror?.[i]||1))),pq=part.q||[0,0,0,1],p=rotate(local.map((v,i)=>v-part.c[i]),[-pq[0],-pq[1],-pq[2],pq[3]]),closest=rotate(p.map((v,i)=>Math.max(-part.s[i]/2,Math.min(part.s[i]/2,v))),pq).map((v,i)=>(v+part.c[i])*object.size[i]*(object.mirror?.[i]||1)),world=rotate(closest,pose.q).map((v,i)=>v+pose.p[i]);return Math.hypot(...world.map((v,i)=>v-point[i]));}
export function socketConnections(project){const objects=new Map(project.objects.map(o=>[o.id,o])),pairs=new Map();for(const c of project.connections||[]){if(!c.ragdoll||!c.b)continue;const a=objects.get(c.a),b=objects.get(c.b);if(!a?.group||!b?.group)continue;const key=[a.group,b.group].sort().join('|');pairs.set(key,c);}return pairs;}
export function insideJointSocket(a,b,pa,pb,partA,partB,c,jointPose,jointObject){if(!c)return false;const point=rotate(localAnchor(jointObject,c.anchorA),jointPose.q).map((v,i)=>v+jointPose.p[i]),radius=c.clearance??.13;return distanceToCollider(point,a,partA,pa)<=radius&&distanceToCollider(point,b,partB,pb)<=radius;}
